"""Browser journey: risk indicators and resilience (Stage 21). Run via e2e/run_all.py."""
from datetime import datetime, timedelta, timezone

from common import *

TODAY = datetime.now(timezone.utc).date()
D = lambda n: (TODAY + timedelta(days=n)).isoformat()
def hrefs(pg): return [a.get_attribute("href") for a in pg.locator(".app-sidebar a").all()]
def tab(pg, name):
    pg.click(f"#rs-tab-{name}"); pg.wait_for_timeout(900)
def body(pg): return pg.inner_text("body")
def err(pg): return txt(pg, ".alert-error")
def A(m, path, who, bodyj=None, org="Meridian"): return api(m, "/resilience" + path, who, org, bodyj)
def st(r): return r.get("status") if isinstance(r, dict) else None
def open_kri(pg, ref):
    tab(pg, "kris"); pg.click(f"#rs-kri-open-{ref}"); pg.wait_for_timeout(900)
KRI = dict(name="Overdue invoices", description="Share of invoices more than 30 days overdue", unit="%", direction="HIGHER_IS_WORSE", amber="10", red="20", owner_name="Ada Obi", review_days=30)
PROC = dict(name="Payroll processing", description="Monthly payroll calculation and payment", owner_name="Ben Eze", rto_hours=24, rpo_hours=4, impact_financial="HIGH", impact_legal="MEDIUM", impact_reputation="LOW")

start_web()
p, b, pg, errs = session()

# ---- an accountant has no business here ----
sign_in(pg, *AISHA, "Meridian"); goto(pg, "/resilience")
check("the menu does not offer the workspace to an accountant", "#/resilience" not in hrefs(pg), hrefs(pg))
check("typing the address shows no content", "Propose an indicator" not in body(pg) and "Record a loss" not in body(pg), body(pg)[:200])
check("the server refuses an accountant (overview)", st(A("GET", "/overview", AISHA)) == 403)
check("the server refuses an accountant (kris)", st(A("GET", "/kris", AISHA)) == 403)

