pg.select_option("#rs-proc-fin", "HIGH"); pg.select_option("#rs-proc-leg", "MEDIUM"); pg.select_option("#rs-proc-rep", "LOW"); pg.click("#rs-proc-save"); pg.wait_for_timeout(400)
check("a recovery time of zero is stopped", "1 to 8760" in txt(pg, "#process-problem"), txt(pg, "#process-problem"))
pg.fill("#rs-proc-rto", "24"); pg.click("#rs-proc-save"); pg.wait_for_timeout(1500)
check("the process is proposed with the highest impact as its criticality", "BP-001" in txt(pg, "#rs-processes") and "High" in txt(pg, "[data-process='BP-001']"), txt(pg, "[data-process='BP-001']"))
