check("a near miss with an amount is refused", st(A("POST", "/losses", TUNDE, dict(title="Near miss with money", description="A near miss must not carry an amount", category="OTHER", kind="NEAR_MISS", occurred_on=D(-3), discovered_on=D(-3), amount="5.00", currency="NGN"))) == 400)
check("a loss without an amount is refused", st(A("POST", "/losses", TUNDE, dict(title="Loss without money", description="A loss needs an amount and a currency", category="OTHER", kind="LOSS", occurred_on=D(-3), discovered_on=D(-3)))) == 400)
check("found before it happened is refused", st(A("POST", "/losses", TUNDE, dict(title="Dates the wrong way", description="Found before it happened is impossible", category="OTHER", kind="LOSS", occurred_on=D(-3), discovered_on=D(-6), amount="1.00", currency="NGN"))) == 400)
check("a future date is refused", st(A("POST", "/losses", TUNDE, dict(title="Happened tomorrow", description="Something that has not happened yet", category="OTHER", kind="NEAR_MISS", occurred_on=D(5), discovered_on=D(5)))) == 400)
pg.reload(); pg.wait_for_timeout(1500); tab(pg, "overview")
check("loss totals are per currency and never added together", "NGN: 2499.50" in txt(pg, "#rs-totals") and "USD: 200.00" in txt(pg, "#rs-totals"), txt(pg, "#rs-totals"))
