check("the other company's overview is empty", A("GET", "/overview", OTHER, org="Other")["counts"]["kris_active"] == 0)
acts = api("GET", "/_audit", DARA, "Meridian")["actions"]
for a_ in ("RESILIENCE_KRI_PROPOSED", "RESILIENCE_KRI_APPROVED", "RESILIENCE_READING_RECORDED", "RESILIENCE_READING_CONFIRMED", "RESILIENCE_LOSS_RECORDED", "RESILIENCE_LOSS_REVIEWED", "RESILIENCE_LOSS_VOIDED", "RESILIENCE_PROCESS_APPROVED", "RESILIENCE_DRILL_RECORDED", "RESILIENCE_DRILL_APPROVED"):
    check(f"the audit trail has {a_}", a_ in acts, [x for x in acts if "RESILIENCE" in x])
check("no content is copied into the audit trail", "Late payers" not in str(api("GET", "/_audit", DARA, "Meridian")))
check("no page errors in the browser", not errs, errs[:3])
finish(p, b)
